local p=game.Players.LocalPlayer local g=p:FindFirstChild("PlayerGui") or game:GetService("CoreGui") if gethui then pcall(function() g=gethui() end) end for _,v in pairs(g:GetChildren()) do if v.Name=="A" then v:Destroy() end end
local sg=Instance.new("ScreenGui",g) sg.Name="A" sg.ResetOnSpawn=false
local bola=Instance.new("TextButton",sg) bola.Size=UDim2.new(0,60,0,60) bola.Position=UDim2.new(0.05,0,0.5,0) bola.Text="A" bola.BackgroundColor3=Color3.fromRGB(255,0,0) bola.TextColor3=Color3.new(1,1,1) bola.Font=Enum.Font.GothamBlack bola.TextSize=28 Instance.new("UICorner",bola).CornerRadius=UDim.new(1,0) bola.Active=true bola.Draggable=true
local m=Instance.new("Frame",sg) m.Size=UDim2.new(0,220,0,280) m.Position=UDim2.new(0.5,-110,0.5,-140) m.BackgroundColor3=Color3.fromRGB(18,18,18) m.Visible=true Instance.new("UICorner",m).CornerRadius=UDim.new(0,10)
local function btn(t,y,c) local b=Instance.new("TextButton",m) b.Size=UDim2.new(0.9,0,0,24) b.Position=UDim2.new(0.05,0,0,y) b.Text=t b.BackgroundColor3=c b.TextColor3=Color3.new(1,1,1) b.Font=Enum.Font.GothamBold b.TextSize=10 Instance.new("UICorner",b).CornerRadius=UDim.new(0,6) return b end
local b1=btn("Speed 500",8,Color3.fromRGB(0,170,0)) local b2=btn("Speed 1000",34,Color3.fromRGB(0,200,0)) local b3=btn("Speed 2000 ULTRA",60,Color3.fromRGB(255,0,0)) local b4=btn("Guardar Base",86,Color3.fromRGB(255,165,0)) local b5=btn("TP BASE SIN LAG",112,Color3.fromRGB(0,200,100)) local b6=btn("AUTO ROBAR OFF",138,Color3.fromRGB(150,0,150)) local b7=btn("AUTO BATE OFF",164,Color3.fromRGB(255,100,0)) local b8=btn("Cerrar",190,Color3.fromRGB(80,0,0))
bola.MouseButton1Click:Connect(function() m.Visible=not m.Visible end)
local function setSpeed(s) p.Character:FindFirstChildOfClass("Humanoid").WalkSpeed=s end
b1.MouseButton1Click:Connect(function() setSpeed(500) end) b2.MouseButton1Click:Connect(function() setSpeed(1000) end) b3.MouseButton1Click:Connect(function() setSpeed(2000) end)
local base=nil b4.MouseButton1Click:Connect(function() base=p.Character.HumanoidRootPart.CFrame b4.Text="Guardada!" wait(1) b4.Text="Guardar Base" end)
local function tpNoLag(cf) local hrp=p.Character.HumanoidRootPart hrp.Velocity=Vector3.new(0,0,0) hrp.CFrame=cf+Vector3.new(0,5,0) wait(0.05) hrp.Velocity=Vector3.new(0,0,0) end
b5.MouseButton1Click:Connect(function() if base then tpNoLag(base) end end) b8.MouseButton1Click:Connect(function() sg:Destroy() end)
local auto=false b6.MouseButton1Click:Connect(function() auto=not auto b6.Text="AUTO ROBAR "..(auto and "ON" or "OFF") end)
local autoBate=false b7.MouseButton1Click:Connect(function() autoBate=not autoBate b7.Text="